// Taming monsters, the silly way. Hand-written (not generated).
//
//   Skeleton: give it a bucket of milk. It finally gets its calcium.
//   Zombie:   give it a cake. Turns out it just wanted someone to remember its birthday.
//   Creeper:  sneak up on it with an empty hand and give it a hug. It's nervous: most hugs end
//             in a (harmless) sneeze that blows you backwards. Keep trying.
//
// The entity files (generated by tools/gen_tame.py) give each mob a tameable component that
// never tames on its own, plus an interact button. This script decides when the funny thing
// worked and calls tame(). Tamed monsters also get sunscreen (fire resistance), so they don't
// burn in daylight.

import { world, system, ItemStack, GameMode } from "@minecraft/server";

const TAMED_TAG = "bigcat_tamed_monster";
const HUG_SUCCESS_CHANCE = 0.35;
const COOLDOWN_TICKS = 10;

const lastTry = new Map();

function tell(player, text) {
  player.onScreenDisplay.setActionBar(text);
}

function pick(list) {
  return list[Math.floor(Math.random() * list.length)];
}

function above(entity, dy) {
  const l = entity.location;
  return { x: l.x, y: l.y + dy, z: l.z };
}

function heldItem(player) {
  const container = player.getComponent("minecraft:inventory")?.container;
  if (!container) return undefined;
  const slot = player.selectedSlotIndex;
  return { container, slot, item: container.getItem(slot) };
}

function isCreative(player) {
  return player.getGameMode() === GameMode.Creative;
}

/** Use up one of the held item (survival only). A milk bucket leaves an empty bucket. */
function consume(player, held, leaves) {
  if (isCreative(player)) return;
  const { container, slot, item } = held;
  if (item.amount > 1) {
    item.amount -= 1;
    container.setItem(slot, item);
    if (leaves) container.addItem(new ItemStack(leaves, 1));
  } else {
    container.setItem(slot, leaves ? new ItemStack(leaves, 1) : undefined);
  }
}

function celebrate(mob, player, line, sound) {
  const tameable = mob.getComponent("minecraft:tameable");
  tameable.tame(player);
  mob.addTag(TAMED_TAG);
  const dim = mob.dimension;
  for (let i = 0; i < 5; i++) {
    dim.spawnParticle("minecraft:heart_particle", {
      x: mob.location.x + (Math.random() - 0.5),
      y: mob.location.y + 1.6 + Math.random() * 0.6,
      z: mob.location.z + (Math.random() - 0.5),
    });
  }
  dim.spawnParticle("minecraft:totem_particle", above(mob, 1));
  if (sound) dim.playSound(sound, mob.location);
  dim.playSound("random.levelup", mob.location, { pitch: 1.6, volume: 0.6 });
  player.onScreenDisplay.setTitle("§aTamed!", { subtitle: line, fadeInDuration: 5, stayDuration: 50, fadeOutDuration: 10 });
}

function tameSkeleton(player, mob, held) {
  if (held.item?.typeId !== "minecraft:milk_bucket") return false;
  consume(player, held, "minecraft:bucket");
  mob.dimension.playSound("random.drink", mob.location);
  celebrate(
    mob,
    player,
    pick([
      "The skeleton finally got its calcium!",
      "Strong bones! The skeleton is yours now.",
      "*crunchy happy noises*",
    ]),
    "mob.skeleton.say"
  );
  return true;
}

function tameZombie(player, mob, held) {
  if (held.item?.typeId !== "minecraft:cake") return false;
  consume(player, held);
  mob.dimension.playSound("random.burp", mob.location);
  mob.dimension.spawnParticle("minecraft:note_particle", above(mob, 2.2));
  celebrate(
    mob,
    player,
    pick([
      "Nobody ever remembered its birthday. Until you.",
      "BRAAAINS... and cake. Mostly cake.",
      "The zombie is so happy it forgot to bite you.",
    ]),
    "mob.zombie.say"
  );
  return true;
}

function hugCreeper(player, mob, held) {
  if (!player.isSneaking) {
    tell(player, "§7Creepers are shy. Sneak up on it first.");
    return true;
  }
  if (held.item) {
    tell(player, "§7You need both arms free for a proper hug.");
    return true;
  }
  if (Math.random() < HUG_SUCCESS_CHANCE) {
    celebrate(
      mob,
      player,
      pick(["The creeper melts into your hug. Ssssweet.", "It hisses... affectionately?", "Best friends. Do not set it on fire."]),
      "mob.creeper.say"
    );
    return true;
  }
  // The sneeze: looks and sounds like an explosion, hurts nobody, but launches you backwards.
  const dim = mob.dimension;
  dim.spawnParticle("minecraft:large_explosion", above(mob, 1));
  dim.playSound("random.explode", mob.location, { pitch: 1.8, volume: 0.5 });
  const dx = player.location.x - mob.location.x;
  const dz = player.location.z - mob.location.z;
  const len = Math.hypot(dx, dz) || 1;
  try {
    player.applyKnockback({ x: (dx / len) * 2.2, z: (dz / len) * 2.2 }, 0.6);
  } catch {}
  tell(player, pick(["§eA-CHOO! The creeper sneezed on you.", "§eToo much hug. It sneezed.", "§eBless you, creeper. Try again."]));
  return true;
}

const HANDLERS = {
  "minecraft:skeleton": tameSkeleton,
  "minecraft:zombie": tameZombie,
  "minecraft:creeper": hugCreeper,
};

world.beforeEvents.playerInteractWithEntity.subscribe((ev) => {
  const handler = HANDLERS[ev.target?.typeId];
  if (!handler) return;
  const tameable = ev.target.getComponent("minecraft:tameable");
  if (!tameable || tameable.isTamed) return;
  const item = ev.itemStack?.typeId;
  const relevant =
    (ev.target.typeId === "minecraft:skeleton" && item === "minecraft:milk_bucket") ||
    (ev.target.typeId === "minecraft:zombie" && item === "minecraft:cake") ||
    (ev.target.typeId === "minecraft:creeper" && !item);
  if (!relevant) return;
  ev.cancel = true; // don't drink the milk / place the cake / poke the creeper
  const { player, target } = ev;
  system.run(() => {
    const now = system.currentTick;
    if (now - (lastTry.get(player.id) ?? -1000) < COOLDOWN_TICKS) return;
    lastTry.set(player.id, now);
    if (!target.isValid) return;
    const held = heldItem(player);
    if (held) handler(player, target, held);
  });
});

// Sunscreen: tamed monsters don't burn in daylight.
system.runInterval(() => {
  for (const dimId of ["minecraft:overworld", "minecraft:nether", "minecraft:the_end"]) {
    let dim;
    try {
      dim = world.getDimension(dimId);
    } catch {
      continue;
    }
    for (const mob of dim.getEntities({ tags: [TAMED_TAG] })) {
      try {
        mob.addEffect("minecraft:fire_resistance", 120, { showParticles: false });
        mob.extinguishFire();
      } catch {}
    }
  }
}, 60);
